from decimal import Decimal, ROUND_HALF_UP

Q=Decimal('0.01')

def _r(x):
    return x.quantize(Q, rounding=ROUND_HALF_UP)

TIER={'platinum':Decimal('0.10'),'gold':Decimal('0.07'),'silver':Decimal('0.03')}

def compute_invoice(lines, customer):
    if not lines:
        raise ValueError('empty')
    for l in lines:
        q=l.get('qty')
        if isinstance(q,bool) or not isinstance(q,int) or q<=0:
            raise ValueError('qty')
        if Decimal(str(l.get('unit_price')))<0:
            raise ValueError('price')
    sub=Decimal('0')
    for l in lines:
        a=Decimal(l['qty'])*Decimal(str(l['unit_price']))
        if l['qty']>=200:
            a*=Decimal('0.88')
        elif l['qty']>=50:
            a*=Decimal('0.95')
        sub+=_r(a)
    disc=_r(sub*TIER.get(customer.get('tier'),Decimal('0')))
    tax=_r((sub-disc)*Decimal('0.10'))
    tot=sub-disc+tax
    return {k:str(_r(v)) for k,v in [('subtotal',sub),('discount',disc),('tax',tax),('total',tot)]}


PFX={'NZD':'NZ$','AUD':'A$','USD':'US$'}

def format_money(amount, currency):
    if currency not in PFX:
        raise ValueError('currency')
    d=_r(Decimal(str(amount)))
    sign='-' if d<0 else ''
    return sign+PFX[currency]+str(abs(d))

